from __future__ import annotations
from typing import Sequence

def cauchy_weight(q: Sequence[float], k: Sequence[float], beta: float = 1.0) -> float:
    if len(q) != len(k): raise ValueError("dimension mismatch")
    if beta <= 0: raise ValueError("beta must be positive")
    return 1.0 / (1.0 + beta * sum((a-b)**2 for a,b in zip(q,k)))

from __future__ import annotations
from typing import Sequence

def audit_active_count(q: Sequence[float], keys: Sequence[Sequence[float]], tau: float) -> tuple[int,float]:
    weights=[1.0/(1.0+sum((a-b)**2 for a,b in zip(q,k))) for k in keys]
    return sum(w >= tau for w in weights), min(weights, default=float("inf"))

from __future__ import annotations
import math

def bandwidth_from_cap_angle(tau: float, half_angle_radians: float) -> float:
    if not 0 < tau < 1: raise ValueError("tau must lie in (0,1)")
    chord2=2.0-2.0*math.cos(half_angle_radians)
    if chord2 <= 0: raise ValueError("cap angle must be positive")
    return (1.0/tau-1.0)/chord2

